import {find,isLocked,clone} from '../document/model.js';
import {enableTrack,putKey,configureAutoKey} from './evaluate.js';
export class MotionRecorder{
 constructor(a,{now=()=>performance.now(),raf=callback=>requestAnimationFrame(callback),cancelRaf=id=>cancelAnimationFrame(id)}={}){this.a=a;this.now=now;this.raf=raf;this.cancelRaf=cancelRaf;this.active=false;}
 begin(gesture){const a=this.a;if(this.active||!a.recordMotionArmed||a.tool!=='select'||a.pivotEdit||gesture.type!=='move'||!gesture.started)return false;const items=gesture.items.filter(item=>find(a.doc,item.id)&&!isLocked(a.doc,item.id));if(!items.length)return false;const startFrame=Math.round(a.time*a.doc.fps);if(startFrame>=600*a.doc.fps){a.recordMotionArmed=false;a.toast?.('Recording ends at 10 minutes. Move the playhead earlier.');return false;}a.pause();this.active=true;this.gesture=gesture;this.items=items;this.fps=a.doc.fps;this.startFrame=startFrame;this.startTime=a.time;this.startedAt=this.now();this.lastFrame=0;this.savedAutoKey=a.autoKey;this.events=[{elapsed:0,poses:items.map(item=>({id:item.id,x:item.v.x,y:item.v.y}))}];a.autoKey=true;configureAutoKey(a.doc,true,'linear');a.time=startFrame/this.fps;a.appearancePreview??=new Map();for(const item of items){const n=find(a.doc,item.id);for(const prop of ['x','y']){enableTrack(n,prop,a.time,'linear');const key=putKey(n,prop,a.time,item.v[prop],'linear');key.easing='linear';delete key.bezier;}}a.motionRecordStatus='Recording motion';this.schedule();return true;}
 schedule(){if(this.active)this.request=this.raf(()=>{this.request=null;this.tick();this.schedule();});}
 pose(poses){if(!this.active)return;const valid=poses.filter(p=>this.items.some(item=>item.id===p.id));this.events.push({elapsed:Math.max(0,this.now()-this.startedAt),poses:clone(valid)});for(const p of valid)this.a.appearancePreview.set(p.id,{...this.a.appearancePreview.get(p.id),x:p.x,y:p.y});}
 poseAt(milliseconds){let event=this.events[0];for(const sample of this.events){if(sample.elapsed>milliseconds+.00001)break;event=sample;}return event.poses;}
 capture(frame,force=false){if(!this.active||!force&&frame<=this.lastFrame)return;const a=this.a,maxFrame=Math.floor(600*this.fps)-this.startFrame;frame=Math.min(frame,maxFrame);const time=(this.startFrame+frame)/this.fps;if(time>a.doc.duration){const before=a.doc.duration;a.doc.duration=Math.min(600,before+Math.ceil(time-before));if(a.doc.playback&&Math.abs(a.doc.playback.end-before)<.00001)a.doc.playback.end=a.doc.duration;}for(const pose of this.poseAt(force?Infinity:frame/this.fps*1000)){const n=find(a.doc,pose.id);if(!n||isLocked(a.doc,n.id))continue;for(const prop of ['x','y']){const key=putKey(n,prop,time,pose[prop],'linear');key.easing='linear';delete key.bezier;}}this.lastFrame=Math.max(this.lastFrame,frame);a.time=time;a.motionRecordStatus='Recording · Frame '+(this.startFrame+frame);}
 tick(){if(!this.active)return;const frame=Math.min(Math.floor((this.now()-this.startedAt)/1000*this.fps),Math.floor(600*this.fps)-this.startFrame);for(let next=this.lastFrame+1;next<=frame;next++)this.capture(next);if(frame>0){const cut=frame/this.fps*1000;let keep=0;for(let i=0;i<this.events.length;i++)if(this.events[i].elapsed<=cut)keep=i;this.events=this.events.slice(keep);}this.a.renderStage();if(this.startFrame+this.lastFrame>=600*this.fps){this.finish();this.a.recordMotionArmed=false;if(this.gesture)this.gesture.edit=false;this.a.history.commit('Record motion');this.a.motionRecordStatus='Recorded · 10 minute limit';this.a.toast?.('Recording stopped at the 10 minute limit.');this.a.render();}}
 clearPreview(){for(const item of this.items||[]){const remaining={...this.a.appearancePreview?.get(item.id)};delete remaining.x;delete remaining.y;if(Object.keys(remaining).length)this.a.appearancePreview.set(item.id,remaining);else this.a.appearancePreview?.delete(item.id);}}
 cleanup(){if(this.request!==null&&this.request!==undefined)this.cancelRaf(this.request);this.request=null;this.clearPreview();this.a.autoKey=this.savedAutoKey;configureAutoKey(this.a.doc,this.savedAutoKey,this.a.ease);this.active=false;}
 finish(){if(!this.active)return false;const frame=Math.max(1,this.lastFrame,Math.round((this.now()-this.startedAt)/1000*this.fps));for(let next=this.lastFrame+1;next<=Math.min(frame,600*this.fps-this.startFrame);next++)this.capture(next);this.capture(Math.min(frame,600*this.fps-this.startFrame),true);this.cleanup();this.a.motionRecordStatus='Recorded '+this.lastFrame+' frames · drag again';return true;}
 cancel({render=true}={}){if(!this.active)return false;const a=this.a;this.cleanup();a.history.cancel();a.time=this.startTime;configureAutoKey(a.doc,a.autoKey,a.ease);if(a.stage?.g===this.gesture)a.stage.g=null;a.motionRecordStatus='Recording cancelled · drag again';if(render)a.render();return true;}
}
